#include <bits/stdc++.h>
using namespace std;
const int N = 3e5 + 5;
int l[N], r[N], n;
string s;
int dfs(int u) {
    if (!u) return 1e9;
    if (!l[u] && !r[u]) return 0;
    int res = 1e9;
    if (l[u]) res = min(res, dfs(l[u]) + (s[u - 1] != 'L'));
    if (r[u]) res = min(res, dfs(r[u]) + (s[u - 1] != 'R'));
    return res;
}
int main() {
    int t; if (!(cin >> t)) return 0;
    while (t--) {
        cin >> n >> s;
        for (int i = 1; i <= n; i++) cin >> l[i] >> r[i];
        cout << dfs(1) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; cin >> t;
    while (t--) {
        int n, k; string s; cin >> n >> k >> s;
        vector<int> low(26, 0), up(26, 0);
        for (char c : s) {
            if (islower(c)) low[c - 'a']++;
            else up[c - 'A']++;
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            int pairs = min(low[i], up[i]);
            ans += pairs;
            low[i] -= pairs; up[i] -= pairs;
            int rem = (low[i] + up[i]) / 2;
            int add = min(rem, k);
            ans += add;
            k -= add;
        }
        cout << ans << "\n";
    }
}

