#include <bits/stdc++.h>
using namespace std;
int n, m;
int grid[1005][1005];
bool vis[1005][1005];
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};
int dfs(int r, int c) {
    vis[r][c] = true;
    int sum = grid[r][c];
    for (int k = 0; k < 4; k++) {
        int nr = r + dx[k], nc = c + dy[k];
        if (nr >= 0 && nr < n && nc >= 0 && nc < m && !vis[nr][nc] && grid[nr][nc] > 0) {
            sum += dfs(nr, nc);
        }
    }
    return sum;
}
int main() {
    int t; cin >> t;
    while (t--) {
        cin >> n >> m;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                cin >> grid[i][j];
                vis[i][j] = false;
            }
        }
        int max_vol = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!vis[i][j] && grid[i][j] > 0) {
                    max_vol = max(max_vol, dfs(i, j));
                }
            }
        }
        cout << max_vol << "\n";
    }
}

