#include <bits/stdc++.h>
using namespace std;
long long gcd(long long a, long long b) { return b ? gcd(b, a % b) : a; }
long long lcm(long long a, long long b) { return (a / gcd(a, b)) * b; }
int main() {
    int t; cin >> t;
    while (t--) {
        long long n, x, y; cin >> n >> x >> y;
        long long c_x = n / x, c_y = n / y, c_xy = n / lcm(x, y);
        long long only_x = c_x - c_xy;
        long long only_y = c_y - c_xy;
        long long sum_x = only_x * (2 * n - only_x + 1) / 2;
        long long sum_y = only_y * (only_y + 1) / 2;
        cout << sum_x - sum_y << "\n";
    }
}

