        int n; double d, h; cin >> n >> d >> h;
        vector<double> y(n);
        for (int i = 0; i < n; i++) cin >> y[i];
        double single_area = 0.5 * d * h;
        double total = single_area * n;
        for (int i = 0; i < n - 1; i++) {
            if (y[i + 1] < y[i] + h) {
                double overlap_h = (y[i] + h) - y[i + 1];
                double overlap_d = d * (overlap_h / h);
