#include <bits/stdc++.h>
using namespace std;
bool solve(int n, int m) {
    if (n == m) return true;
    if (n % 3 != 0 || n < m) return false;
    return solve(n / 3, m) || solve(2 * (n / 3), m);
}
int main() {
    int t; cin >> t;
    while (t--) {
        int n, m; cin >> n >> m;
        cout << (solve(n, m) ? "YES\n" : "NO\n");
