#include <bits/stdc++.h>
using namespace std;
long long count_inv(const vector<int>& v) {
    long long ones = 0, inv = 0;
    for (int x : v) {
        if (x == 1) ones++;
        else inv += ones;
    }
    return inv;
}
int main() {
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        long long ans = count_inv(a);
        vector<int> a1 = a, a2 = a;
        for (int i = 0; i < n; i++) {
            if (a1[i] == 0) { a1[i] = 1; break; }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (a2[i] == 1) { a2[i] = 0; break; }
        }
        ans = max({ans, count_inv(a1), count_inv(a2)});
        cout << ans << "\n";
    }
}

