int main() {
    int t; cin >> t;
    while (t--) {
        int n, s; cin >> n >> s;
        vector<int> a(n);
        int total = 0;
        for (int i = 0; i < n; i++) { cin >> a[i]; total += a[i]; }
        if (total < s) { cout << -1 << "\n"; continue; }
        if (total == s) { cout << 0 << "\n"; continue; }
        int max_len = 0, l = 0, cur = 0;
        for (int r = 0; r < n; r++) {
            cur += a[r];
            while (cur > s) { cur -= a[l++]; }
            if (cur == s) max_len = max(max_len, r - l + 1);
        }
        cout << n - max_len << "\n";
    }
}
